import{_ as s,o as i,c as t,a4 as a}from"./chunks/framework.DCsBdTIw.js";const c=JSON.parse('{"title":"LibreChat","description":"Configure a custom OpenAI-compatible endpoint for Tokeness in LibreChat.","frontmatter":{"title":"LibreChat","description":"Configure a custom OpenAI-compatible endpoint for Tokeness in LibreChat."},"headers":[],"relativePath":"integrations/librechat.md","filePath":"integrations/librechat.md","lastUpdated":1784332800000}'),n={name:"integrations/librechat.md"};function l(o,e,h,d,r,p){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="librechat" tabindex="-1">LibreChat <a class="header-anchor" href="#librechat" aria-label="Permalink to &quot;LibreChat&quot;">​</a></h1><p>LibreChat supports custom OpenAI-compatible endpoints. The common approach is to define the endpoint in <code>librechat.yaml</code> and store the key in <code>.env</code>.</p><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>API URL / Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Models</td><td>Full model names copied from the Tokeness model catalog</td></tr></tbody></table><p>LibreChat is typically used for multi-user chat. In production, do not expose the Tokeness key to the frontend and do not commit it to a repository.</p><h2 id="file-responsibilities" tabindex="-1">File Responsibilities <a class="header-anchor" href="#file-responsibilities" aria-label="Permalink to &quot;File Responsibilities&quot;">​</a></h2><p>A LibreChat custom endpoint typically involves three files:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>librechat.yaml</code></td><td>Defines the custom endpoint, model list, and display name</td></tr><tr><td><code>.env</code></td><td>Stores sensitive information such as API keys</td></tr><tr><td><code>docker-compose.override.yml</code></td><td>Mounts <code>librechat.yaml</code> in Docker deployments</td></tr></tbody></table><p>If you are not using Docker, place <code>librechat.yaml</code> wherever your deployment can read it.</p><h2 id="configure-env" tabindex="-1">Configure .env <a class="header-anchor" href="#configure-env" aria-label="Permalink to &quot;Configure .env&quot;">​</a></h2><p>Add the following to <code>.env</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKENESS_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tokeness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span></span></code></pre></div><p>Do not put the real key in <code>librechat.yaml</code>.</p><h2 id="configure-librechat-yaml" tabindex="-1">Configure librechat.yaml <a class="header-anchor" href="#configure-librechat-yaml" aria-label="Permalink to &quot;Configure librechat.yaml&quot;">​</a></h2><p>Below is a minimal configuration. Replace the model names with the full model names from the Tokeness model catalog.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.2.1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">endpoints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  custom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tokeness&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      apiKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${TOKENESS_API_KEY}&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://n.tokeness.io/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_MODEL_NAME&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      titleConvo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      titleModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_MODEL_NAME&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      modelDisplayLabel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tokeness&quot;</span></span></code></pre></div><p>Field descriptions:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>The endpoint name displayed in LibreChat</td></tr><tr><td><code>apiKey</code></td><td>Reads the Tokeness key from <code>.env</code></td></tr><tr><td><code>baseURL</code></td><td>The Tokeness OpenAI-compatible Base URL</td></tr><tr><td><code>models.default</code></td><td>Models available in the UI</td></tr><tr><td><code>models.fetch</code></td><td>When set to <code>false</code>, uses the manual model list</td></tr><tr><td><code>titleModel</code></td><td>The model used to generate conversation titles</td></tr></tbody></table><p>To expose multiple models:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MODEL_A&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MODEL_B&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MODEL_C&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="docker-mount-configuration" tabindex="-1">Docker Mount Configuration <a class="header-anchor" href="#docker-mount-configuration" aria-label="Permalink to &quot;Docker Mount Configuration&quot;">​</a></h2><p>If you use Docker Compose, you can mount the configuration in <code>docker-compose.override.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./librechat.yaml:/app/librechat.yaml</span></span></code></pre></div><p>After making changes, restart:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><h2 id="let-users-provide-their-own-key" tabindex="-1">Let Users Provide Their Own Key <a class="header-anchor" href="#let-users-provide-their-own-key" aria-label="Permalink to &quot;Let Users Provide Their Own Key&quot;">​</a></h2><p>For an internal team deployment where each user should use their own Tokeness key, change <code>apiKey</code> to:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user_provided&quot;</span></span></code></pre></div><p>In this mode, users enter their own key in the LibreChat UI. It suits scenarios where multiple people share a LibreChat instance but you do not want the server to hold a shared key.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ol><li>Restart LibreChat.</li><li>Select <code>Tokeness</code> in the model endpoint selector.</li><li>Select a configured model.</li><li>Send &quot;reply with ok only&quot;.</li><li>Open the Tokeness usage logs and confirm a request arrived.</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Action</th></tr></thead><tbody><tr><td>Tokeness endpoint not visible</td><td>Check whether <code>librechat.yaml</code> was mounted successfully and restart the container</td></tr><tr><td>401</td><td>Check that <code>TOKENESS_API_KEY</code> in <code>.env</code> is being read by the container</td></tr><tr><td>404</td><td><code>baseURL</code> should be <code>https://n.tokeness.io/v1</code></td></tr><tr><td>Model dropdown is empty</td><td>Set <code>models.fetch: false</code> and enter model names manually</td></tr><tr><td>Conversation title generation fails</td><td>Check that <code>titleModel</code> is an available model</td></tr><tr><td>Multiple users&#39; keys get mixed up</td><td>Use <code>user_provided</code> so each user enters their own key in the UI</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.librechat.ai/docs/quick_start/custom_endpoints" target="_blank" rel="noreferrer">LibreChat Custom Endpoints</a></li><li><a href="https://www.librechat.ai/docs/configuration/librechat_yaml/object_structure/custom_endpoint" target="_blank" rel="noreferrer">LibreChat Custom Endpoint Object Structure</a></li></ul>`,35)])])}const u=s(n,[["render",l]]);export{c as __pageData,u as default};
